namespace sarif.export.bkmk;






using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifBookmarkWriter : AbstractExtWriter {
	
	private List<Bookmark> bookmarks = new();

	public SarifBookmarkWriter(List<Bookmark> target, Writer baseWriter)
    : base(baseWriter)
    {
		bookmarks = target;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genBookmarks(monitor);
		root.add("bookmarks", objects);
	}

	private void genBookmarks(TaskMonitor monitor)
    {
		monitor.initialize(bookmarks.size());
		foreach (Bookmark b in bookmarks) {
			monitor.checkCancelled();
			ExtBookmark isf = new ExtBookmark(b);
			SarifObject sarif = new SarifObject(BookmarksSarifMgr.SUBKEY, BookmarksSarifMgr.KEY, getTree(isf), b.getAddress(), b.getAddress());
			objects.add(getTree(sarif));
			monitor.increment();
		}
	}
}
